// Nastavení workflow. ŽÁDNÉ klíče ani ID účtů se sem nepíšou natvrdo do repozitáře: tajemství jdou z proměnných prostředí n8n.
let env = {};
try { env = $env; } catch (e) { env = {}; }
const cfg = {
  // tajemství odchozích webhooků (Nastavení → Integrace → webhook → tajemství podpisu, začíná whsec_)
  webhookSecret: env.OPSYS_WEBHOOK_SECRET || '<<DOPLNIT: tajemství webhooku>>',
  // tajemství příchozích požadavků (Nastavení → Integrace → Příchozí požadavky); podepisuje se callback do OPSYS
  ingestSecret: env.OPSYS_INGEST_SECRET || '<<DOPLNIT: tajemství příchozích požadavků>>',
  // ID složek „Klienti“ a „Archiv“ na sdíleném Disku (z adresy složky v prohlížeči: …/folders/<ID>)
  clientsRootFolderId: env.OPSYS_DRIVE_CLIENTS_FOLDER_ID || '<<DOPLNIT: ID složky Klienti>>',
  archiveRootFolderId: env.OPSYS_DRIVE_ARCHIVE_FOLDER_ID || '<<DOPLNIT: ID složky Archiv>>',
};
return $input.all().map((i) => ({ json: { ...i.json, cfg }, binary: i.binary }));

// Ověření podpisu odchozího webhooku OPSYS: hlavička X-Opsys-Signature = t=<unix>,v1=<hex HMAC-SHA256(tajemství, t + "." + tělo)>.
// Tělo se podepisuje přesně tak, jak odešlo, proto se čte ze syrových dat (Webhook → Možnosti → Raw Body), ne z parsovaného JSON.
// Vyžaduje NODE_FUNCTION_ALLOW_BUILTIN=crypto v prostředí n8n.
const crypto = require('crypto');
const item = $input.first();
const cfg = item.json.cfg;
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const header = String((item.json.headers || {})['x-opsys-signature'] || '');
let t = null;
const sigs = [];
for (const part of header.split(',')) {
  const i = part.indexOf('=');
  if (i < 1) continue;
  const k = part.slice(0, i).trim();
  const v = part.slice(i + 1).trim();
  if (k === 't' && /^\d{1,12}$/.test(v)) t = Number(v);
  else if (k === 'v1' && /^[0-9a-f]{64}$/i.test(v)) sigs.push(v.toLowerCase());
}
if (String(cfg.webhookSecret).includes('DOPLNIT')) throw new Error('Workflow není nastavené: chybí tajemství webhooku (uzel Konfigurace).');
let ok = false;
let reason = header ? 'malformed' : 'missing';
if (t !== null && sigs.length) {
  if (Math.abs(Math.floor(Date.now() / 1000) - t) > 300) reason = 'expired';
  else {
    const expected = crypto.createHmac('sha256', cfg.webhookSecret).update(t + '.' + raw).digest();
    ok = sigs.some((s) => { const g = Buffer.from(s, 'hex'); return g.length === expected.length && crypto.timingSafeEqual(g, expected); });
    reason = ok ? '' : 'mismatch';
  }
}
let event = null;
if (ok) {
  try { event = JSON.parse(raw); } catch (e) { ok = false; reason = 'invalid_json'; }
}
return [{ json: { ok, reason, event, cfg } }];

// Z události drive.* (viz docs/moduly/disk.md) sestaví plán práce: seznam složek k založení (strom) nebo jedna operace.
const { event, cfg } = $input.first().json;
const d = (event && event.data) || {};
const s = d.structure || {};
const client = d.client || {};
const kind = (event && event.event) || '';
// zkušební událost „Odeslat test“ a cokoli, co není drive.*, se tiše přijme (odpověď 200 už odešla) a workflow skončí
if (!kind.startsWith('drive.')) return [];
const state = {
  requestId: d.requestId || (event && event.id) || '',
  callbackUrl: d.callbackUrl || '',
  kind,
  cfg,
  tasks: [],
  error: null,
  update: null,
  move: null,
  lookup: null,
};
let n = 0;
const key = () => 't' + (++n);
// rekurzivně převede strom { name, service?, children } na seznam úkolů (rodič je dřív než potomek)
function flatten(node, parentKey, parentId, role) {
  const k = key();
  state.tasks.push({ key: k, name: String(node.name), parentKey, parentId, role: node.service ? 'service' : role, service: node.service || null, id: null });
  for (const c of node.children || []) flatten(c, k, null, 'sub');
  return k;
}
let op = 'tree';
if (!state.requestId || !/^https?:\/\//.test(state.callbackUrl)) {
  state.error = 'Událost neobsahuje requestId nebo callbackUrl.';
} else if (String(cfg.clientsRootFolderId).includes('DOPLNIT') || String(cfg.archiveRootFolderId).includes('DOPLNIT')) {
  state.error = 'Workflow není nastavené: chybí ID složek Klienti a Archiv (uzel Konfigurace).';
} else if (kind === 'drive.client.create') {
  flatten(s.clientFolder, null, cfg.clientsRootFolderId, 'client');
} else if (kind === 'drive.client.add_service') {
  if (!client.folderId) state.error = 'Klient nemá složku na Disku (folderId).';
  else for (const svc of s.services || []) flatten({ name: svc.name, service: svc.service, children: svc.children }, null, client.folderId, 'service');
} else if (kind === 'drive.project.create') {
  const sf = s.serviceFolder || {};
  if (!client.folderId) state.error = 'Klient nemá složku na Disku (folderId).';
  else if (sf.folderId) flatten(s.jobFolder, null, sf.folderId, 'project');
  else {
    // složka služby není známá: najít ji v klientské složce, jinak založit (vždy „najít, nebo založit“)
    flatten({ name: sf.name, service: sf.service, children: [] }, null, client.folderId, 'service');
    state.tasks[state.tasks.length - 1].key = 'svc';
    flatten(s.jobFolder, 'svc', null, 'project');
    const esc = (v) => String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    state.lookup = { q: "name = '" + esc(sf.name) + "' and '" + client.folderId + "' in parents and mimeType = 'application/vnd.google-apps.folder' and trashed = false" };
    op = 'lookup';
  }
} else if (kind === 'drive.client.rename') {
  if (!client.folderId) state.error = 'Klient nemá složku na Disku (folderId).';
  else { state.update = { fileId: client.folderId, name: String((s.clientFolder || {}).name || '') }; op = 'update'; }
} else if (kind === 'drive.client.archive') {
  if (!client.folderId) state.error = 'Klient nemá složku na Disku (folderId).';
  else { state.move = { fileId: client.folderId, add: cfg.archiveRootFolderId, remove: cfg.clientsRootFolderId }; op = 'move'; }
} else if (kind === 'drive.client.restore') {
  if (!client.folderId) state.error = 'Klient nemá složku na Disku (folderId).';
  else { state.move = { fileId: client.folderId, add: cfg.clientsRootFolderId, remove: cfg.archiveRootFolderId }; op = 'move'; }
} else {
  state.error = 'Neznámá událost: ' + kind;
}
// kořenová složka zakázky/klienta má vždy roli podle druhu události
if (kind === 'drive.client.create' && state.tasks[0]) state.tasks[0].role = 'client';
if (state.error) op = 'tree';
return [{ json: { op, state } }];

// Vybere složky, jejichž rodič už má ID (nejdřív kořen, pak další úroveň…). Když nic nezbývá nebo nastala chyba, je hotovo.
const state = $input.first().json.state;
if (state.error) return [{ json: { done: true, state } }];
const idOf = Object.fromEntries(state.tasks.filter((t) => t.id).map((t) => [t.key, t.id]));
const ready = state.tasks.filter((t) => !t.id && (t.parentKey ? idOf[t.parentKey] : t.parentId));
if (!ready.length) return [{ json: { done: true, state } }];
return ready.map((t) => ({ json: { done: false, key: t.key, name: t.name, parentId: t.parentKey ? idOf[t.parentKey] : t.parentId, state } }));

// Přiřadí ID založených složek ke svým úkolům (podle pořadí položek) a vrátí aktualizovaný stav do smyčky.
const planned = $('Další úroveň').all();
const res = $input.all();
const state = JSON.parse(JSON.stringify(planned[0].json.state));
planned.forEach((p, i) => {
  const r = (res[i] && res[i].json) || {};
  const t = state.tasks.find((x) => x.key === p.json.key);
  if (r.id && !r.error) t.id = r.id;
  else if (!state.error) {
    const e = r.error || {};
    state.error = 'Složku „' + p.json.name + '“ se nepodařilo založit: ' + (e.message || e.description || 'neznámá chyba Google Disku') + '.';
  }
});
return [{ json: { state } }];

// Z hotových úkolů sestaví tělo callbacku (status ok/error, ID složek podle role).
const state = $input.first().json.state;
const cb = { eventId: state.requestId, status: state.error ? 'error' : 'ok' };
if (state.error) cb.error = String(state.error).slice(0, 1900);
else {
  const folders = {};
  const client = state.tasks.find((t) => t.role === 'client');
  if (client && client.id) folders.root = client.id;
  const services = {};
  for (const t of state.tasks) if (t.role === 'service' && t.service && t.id) services[t.service] = t.id;
  if (Object.keys(services).length) folders.services = services;
  const project = state.tasks.find((t) => t.role === 'project');
  if (project && project.id) folders.project = project.id;
  if (Object.keys(folders).length) cb.folders = folders;
}
return [{ json: { callbackUrl: state.callbackUrl, ingestSecret: state.cfg.ingestSecret, callback: cb } }];

// Našla-li se složka služby, použije se její ID; jinak ji smyčka založí (úkol 'svc').
const state = JSON.parse(JSON.stringify($('Plán').first().json.state));
const r = $input.first().json || {};
if (r.error) {
  state.error = 'Hledání složky služby selhalo: ' + ((r.error && (r.error.message || r.error.description)) || 'neznámá chyba Google Disku') + '.';
} else {
  const found = Array.isArray(r.files) ? r.files[0] : null;
  if (found && found.id) state.tasks.find((t) => t.key === 'svc').id = found.id;
}
return [{ json: { state } }];

// Výsledek přejmenování / přesunu pro callback.
const state = $('Plán').first().json.state;
const r = $input.first().json || {};
const fileId = (state.update || state.move || {}).fileId;
const cb = { eventId: state.requestId };
if (r.error || !r.id) {
  cb.status = 'error';
  const e = r.error || {};
  cb.error = ('Operace na Disku selhala: ' + (e.message || e.description || 'neznámá chyba Google Disku') + '.').slice(0, 1900);
} else {
  cb.status = 'ok';
  if (state.kind === 'drive.client.archive') cb.folders = { archive: r.id };
  else cb.folders = { root: r.id };
}
return [{ json: { callbackUrl: state.callbackUrl, ingestSecret: state.cfg.ingestSecret, callback: cb, fileId } }];

// Podepíše tělo callbacku tajemstvím příchozích požadavků: X-Opsys-Signature = t=<unix>,v1=<hex HMAC-SHA256(tajemství, t + "." + tělo)>.
// Tělo se serializuje JEDNOU a odešle se přesně tak (HTTP uzel níže posílá surový řetězec).
const crypto = require('crypto');
const j = $input.first().json;
if (String(j.ingestSecret).includes('DOPLNIT')) throw new Error('Workflow není nastavené: chybí tajemství příchozích požadavků (uzel Konfigurace).');
const body = JSON.stringify(j.callback);
const t = Math.floor(Date.now() / 1000);
const sig = crypto.createHmac('sha256', j.ingestSecret).update(t + '.' + body).digest('hex');
return [{ json: { url: j.callbackUrl, body, signature: 't=' + t + ',v1=' + sig } }];
